// Package relayproof implements cross-chain message verification.
package relayproof

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"sync"
	"syscall"
)

// Header is a light-client header at a known height.
type Header struct {
	Chain   string
	Height  int64
	Root    string
	Trusted bool
}

// Message is one outbound cross-chain message awaiting delivery.
type Message struct {
	ID      string
	From    string
	To      string
	Nonce   uint64
	Payload string
	ProofAt int64
}

// Delivery is the outcome of a relay attempt.
type Delivery struct {
	Message string
	Status  string
	Reason  string
}

// Verify accepts a message only when the header covering it is known and trusted.
func Verify(headers map[string]Header, message Message, consumed map[string]bool) Delivery {
	header, ok := headers[message.From]
	if !ok {
		return Delivery{Message: message.ID, Status: "rejected", Reason: "unknown source chain"}
	}
	if !header.Trusted || header.Height < message.ProofAt {
		return Delivery{Message: message.ID, Status: "pending", Reason: "header not yet trusted at proof height"}
	}
	key := message.From + ":" + message.To + ":" + strconv.FormatUint(message.Nonce, 10)
	if consumed[key] {
		return Delivery{Message: message.ID, Status: "rejected", Reason: "replay: nonce already consumed"}
	}
	consumed[key] = true
	return Delivery{Message: message.ID, Status: "delivered", Reason: "proof verified at height " + strconv.FormatInt(header.Height, 10)}
}

// Pending lists messages still waiting for a trusted header, stable by id.
func Pending(headers map[string]Header, messages []Message) []string {
	var ids []string
	for _, message := range messages {
		header, ok := headers[message.From]
		if !ok || !header.Trusted || header.Height < message.ProofAt {
			ids = append(ids, message.ID)
		}
	}
	sort.Strings(ids)
	return ids
}

// Terminal message statuses.
const (
	StatusSuccess      = "success"       // delivered: recorded locally and nonce consumed
	StatusReplay       = "replay"        // terminal: nonce combination already consumed by another message
	StatusExpired      = "expired"       // terminal: absolute expiry reached before delivery
	StatusUnknownSrc   = "unknown-source" // terminal: source chain was never registered
	StatusPending      = "pending"       // accepted, not processed for the first time yet
	StatusWaiting      = "waiting"       // processed, waiting for a trusted header at proof height
)

// Common errors. Callers can compare with errors.Is.
var (
	// ErrConflict is returned when an id is reused with different message content.
	ErrConflict = errors.New("message id conflict: existing record has different content")
	// ErrTerminal is returned when a terminal message is submitted again or re-activated
	// through a header update.
	ErrTerminal = errors.New("message is terminal and cannot be reactivated")
	// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
	ErrInvalidArg = errors.New("invalid argument")
	// ErrLocked is returned when another process holds the state directory open.
	ErrLocked = errors.New("state directory is locked by another process")
	// ErrCorrupt is returned when the state directory contains unreadable state.
	ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
)

// Envelope is a submitted message together with its absolute expiry time.
type Envelope struct {
	Message Message
	// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
	ExpiresAt int64
}

// Record is the full persisted state of one submitted message.
type Record struct {
	Msg        Envelope
	Status     string
	Reason     string
	Seq        int64 // submission order, zero-based
	Attempts   int
	NextRetry  int64 // 0 when not yet processed for the first time, or terminal
	LastProcAt int64 // processing time of the most recent Advance that touched it
}

// Query is the user-visible view of a Record.
type Query struct {
	ID         string
	From       string
	To         string
	Nonce      uint64
	Payload    string
	ProofAt    int64
	ExpiresAt  int64
	Status     string
	Reason     string
	NextRetry  int64 // 0 = no retry scheduled
	Attempts   int
}

// Result describes what happened to one message during an Advance.
type Result struct {
	ID     string
	Status string
	Reason string
}

// AdvanceReport is the outcome of one Advance call.
type AdvanceReport struct {
	Now     int64
	Results []Result
}

func nonceKey(from, to string, nonce uint64) string {
	return from + "\x00" + to + "\x00" + strconv.FormatUint(nonce, 10)
}

// Queue is a durable local outbox. A single Queue owns its state directory for
// writes; other processes attempting to Open the same directory fail with
// ErrLocked. The Queue is safe for concurrent use by multiple goroutines.
type Queue struct {
	mu sync.Mutex

	store *store
	flock *os.File

	now      int64                 // last advanced time (Unix ms), 0 = never advanced
	sources  map[string]bool       // registered source chains
	headers  map[string]Header     // latest registered header per chain
	records  map[string]*Record    // by message id
	order    []string              // submission order of all non-terminal messages
	consumed map[string]string     // nonce combination -> id of the successful message
	nextSeq  int64
}

// Open opens (creating if needed) a persistent queue backed by stateDir.
// It takes an exclusive process lock on the directory and refuses to start
// when the on-disk state is corrupt or in an unsupported format.
func Open(stateDir string) (*Queue, error) {
	if stateDir == "" {
		return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
	}
	if err := os.MkdirAll(stateDir, 0o755); err != nil {
		return nil, fmt.Errorf("create state directory: %w", err)
	}
	abs, err := filepath.Abs(stateDir)
	if err != nil {
		return nil, fmt.Errorf("resolve state directory: %w", err)
	}

	lockPath := filepath.Join(abs, "lock")
	lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, fmt.Errorf("open lock file: %w", err)
	}
	if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		lock.Close()
		return nil, fmt.Errorf("%w: %v", ErrLocked, err)
	}

	st, err := openStore(abs)
	if err != nil {
		syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
		lock.Close()
		return nil, err
	}

	q := &Queue{
		store:    st,
		flock:    lock,
		sources:  map[string]bool{},
		headers:  map[string]Header{},
		records:  map[string]*Record{},
		consumed: map[string]string{},
	}
	if err := q.load(); err != nil {
		st.close()
		syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
		lock.Close()
		return nil, err
	}
	return q, nil
}

// Close flushes pending state, releases the directory lock and closes the queue.
func (q *Queue) Close() error {
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.flock == nil {
		return nil
	}
	err := q.store.close()
	syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
	q.flock.Close()
	q.flock = nil
	return err
}

// RegisterSource records that messages may originate from chain. It is idempotent.
func (q *Queue) RegisterSource(chain string) error {
	if chain == "" {
		return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.sources[chain] {
		return nil
	}
	if err := q.store.appendRegisterSource(chain); err != nil {
		return err
	}
	q.sources[chain] = true
	return nil
}

// UpsertHeader stores the latest known header for a chain. A header with
// trusted=false records the chain tip without granting proof coverage; a
// later trusted header covering the proof height can unblock messages.
// Header updates never bypass retry scheduling and never reactivate terminal
// messages.
func (q *Queue) UpsertHeader(h Header) error {
	if h.Chain == "" {
		return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
	}
	if h.Height < 0 {
		return fmt.Errorf("%w: negative header height", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.store.appendHeader(h); err != nil {
		return err
	}
	q.headers[h.Chain] = h
	return nil
}

// Submit enqueues a message with an absolute expiry time (Unix milliseconds;
// zero means never expire). Re-submitting the same id with identical content
// returns the existing record without adding a queue entry; the same id with
// different content returns ErrConflict and leaves the original untouched;
// re-submitting a terminal id returns ErrTerminal.
//
// Durability: success is reported only after the message is reliably persisted.
func (q *Queue) Submit(env Envelope) (*Record, error) {
	m := env.Message
	if m.ID == "" {
		return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
	}
	if m.From == "" || m.To == "" {
		return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
	}
	if m.ProofAt < 0 {
		return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
	}
	if env.ExpiresAt < 0 {
		return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
	}

	q.mu.Lock()
	defer q.mu.Unlock()

	if existing, ok := q.records[m.ID]; ok {
		if sameEnvelope(existing.Msg, env) {
			return existing, nil
		}
		if isTerminal(existing.Status) {
			return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
		}
		return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
	}

	rec := &Record{
		Msg:    env,
		Status: StatusPending,
		Reason: "awaiting first processing",
		Seq:    q.nextSeq,
	}
	if err := q.store.appendSubmit(rec); err != nil {
		return nil, err
	}
	q.records[m.ID] = rec
	q.order = append(q.order, m.ID)
	q.nextSeq++
	return rec, nil
}

// Advance moves processing time forward to nowMs (Unix milliseconds). Equal
// time may be advanced repeatedly; going backwards is rejected without
// changing any state. Each advance:
//
//  1. accepts first-time processing for new messages when now has reached
//     their first processing time;
//  2. checks replay and expiry (replay wins when both hold; exactly reaching
//     the expiry instant counts as expired) for every non-terminal message;
//  3. then processes messages whose retry time has come, in first-submission
//     order.
//
// Messages from unregistered sources are permanently rejected as unknown
// source. Registered sources with an untrusted or insufficient header stay
// waiting and do not consume the nonce. Retry intervals are 1,2,4,... seconds,
// doubling up to a 60 second cap, computed from the actual processing time.
func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
	if nowMs < 0 {
		return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()

	if q.now != 0 && nowMs < q.now {
		return nil, fmt.Errorf("%w: processing time %d is before last advanced time %d", ErrInvalidArg, nowMs, q.now)
	}
	now := nowMs

	report := &AdvanceReport{Now: now}
	// Snapshot ids: terminalization mutates q.order.
	ids := append([]string(nil), q.order...)
	for _, id := range ids {
		rec := q.records[id]
		if rec == nil || isTerminal(rec.Status) {
			continue
		}
		if rec.Attempts == 0 {
			// First processing is accepted on the next advance after submission.
		} else if now < rec.NextRetry {
			continue
		}

		// Replay and expiry are evaluated on every processing opportunity.
		// Replay takes precedence when both hold.
		key := nonceKey(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
		if winner, taken := q.consumed[key]; taken && winner != id {
			if err := q.terminalize(rec, now, StatusReplay,
				"nonce already consumed by message "+winner); err != nil {
				return nil, err
			}
			report.Results = append(report.Results, Result{ID: id, Status: StatusReplay, Reason: rec.Reason})
			continue
		}
		if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
			if err := q.terminalize(rec, now, StatusExpired,
				"expired at "+strconv.FormatInt(rec.Msg.ExpiresAt, 10)); err != nil {
				return nil, err
			}
			report.Results = append(report.Results, Result{ID: id, Status: StatusExpired, Reason: rec.Reason})
			continue
		}

		h, registered := q.headers[rec.Msg.Message.From]
		if !q.sources[rec.Msg.Message.From] {
			// Permanent rejection: the source can never become valid mid-flight,
			// because submitting does not register a source.
			if err := q.terminalize(rec, now, StatusUnknownSrc,
				"unknown source chain "+rec.Msg.Message.From); err != nil {
				return nil, err
			}
			report.Results = append(report.Results, Result{ID: id, Status: Status, Reason: rec.Reason})
			continue
		}
		if !registered || !h.Trusted || h.Height < rec.Msg.Message.ProofAt {
			cur := h.Height
			if !registered {
				cur = 0
			}
			if err := q.markWaiting(rec, now,
				fmt.Sprintf("waiting for trusted header at height %d (current %d)", rec.Msg.Message.ProofAt, cur)); err != nil {
				return nil, err
			}
			report.Results = append(report.Results, Result{ID: id, Status: StatusWaiting, Reason: rec.Reason})
			continue
		}

		// Success: recording the success and consuming the nonce commit
		// atomically in one log entry; they can never take effect separately.
		if err := q.store.appendResult(now, rec, StatusSuccess,
			"delivered at height "+strconv.FormatInt(h.Height, 10), rec.Attempts+1,
			nextRetryDelay(rec.Attempts+1), key, id, true); err != nil {
			return nil, err
		}
		rec.Attempts++
		rec.LastProcAt = now
		rec.Status = StatusSuccess
		rec.Reason = "delivered at height " + strconv.FormatInt(h.Height, 10)
		rec.NextRetry = 0
		q.consumed[key] = id
		q.removeFromOrder(id)
		if err := q.store.appendAdvance(now); err != nil {
			return nil, err
		}
		q.now = now
		report.Results = append(report.Results, Result{ID: id, Status: StatusSuccess, Reason: rec.Reason})
	}

	if err := q.store.appendAdvance(now); err != nil {
		return nil, err
	}
	q.now = now
	return report, nil
}

// Query returns the current state of a message.
func (q *Queue) Query(id string) (Query, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	rec, ok := q.records[id]
	if !ok {
		return Query{}, false
	}
	return toQuery(rec), true
}

// Queries returns all records in first-submission order.
func (q *Queue) Queries() []Query {
	q.mu.Lock()
	defer q.mu.Unlock()
	out := make([]Query, 0, len(q.records))
	for _, rec := range q.records {
		out = append(out, toQuery(rec))
	}
	sort.Slice(out, func(i, j int) bool {
		ri, rj := q.records[out[i].ID], q.records[out[j].ID]
		return ri.Seq < rj.Seq
	})
	return out
}

// Now returns the last advanced processing time, or 0 if never advanced.
func (q *Queue) Now() int64 {
	q.mu.Lock()
	defer q.mu.Unlock()
	return q.now
}

func (q *Queue) terminalize(rec *Record, now int64, status, reason string) error {
	if err := q.store.appendResult(now, rec, status, reason, rec.Attempts+1, 0, "", "", false); err != nil {
		return err
	}
	rec.Attempts++
	rec.LastProcAt = now
	rec.Status = status
	rec.Reason = reason
	rec.NextRetry = 0
	q.removeFromOrder(rec.Msg.Message.ID)
	return nil
}

func (q *Queue) markWaiting(rec *Record, now int64, reason string) error {
	attempt := rec.Attempts + 1
	delay := nextRetryDelay(attempt)
	if err := q.store.appendResult(now, rec, StatusWaiting, reason, attempt, delay, "", "", false); err != nil {
		return err
	}
	rec.Attempts = attempt
	rec.LastProcAt = now
	rec.Status = StatusWaiting
	rec.Reason = reason
	rec.NextRetry = now + delay
	return nil
}

func (q *Queue) removeFromOrder(id string) {
	for i, cand := range q.order {
		if cand == id {
			q.order = append(q.order[:i], q.order[i+1:]...)
			return
		}
	}
}

// nextRetryDelay returns the backoff after attempt (1-based):
// 1s, 2s, 4s, 8s, 16s, 32s, 60s, 60s, ... in milliseconds.
func nextRetryDelay(attempt int) int64 {
	if attempt < 1 {
		attempt = 1
	}
	if attempt > 6 {
		return 60_000
	}
	return int64(1) << (attempt - 1) * 1000
}

func isTerminal(status string) bool {
	switch status {
	case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
		return true
	}
	return false
}

func sameEnvelope(a, b Envelope) bool {
	return a.ExpiresAt == b.ExpiresAt &&
		a.Message.ID == b.Message.ID &&
		a.Message.From == b.Message.From &&
		a.Message.To == b.Message.To &&
		a.Message.Nonce == b.Message.Nonce &&
		a.Message.Payload == b.Message.Payload &&
		a.Message.ProofAt == b.Message.ProofAt
}

func toQuery(rec *Record) Query {
	return Query{
		ID:        rec.Msg.Message.ID,
		From:      rec.Msg.Message.From,
		To:        rec.Msg.Message.To,
		Nonce:     rec.Msg.Message.Nonce,
		Payload:   rec.Msg.Message.Payload,
		ProofAt:   rec.Msg.Message.ProofAt,
		ExpiresAt: rec.Msg.ExpiresAt,
		Status:    rec.Status,
		Reason:    rec.Reason,
		NextRetry: rec.NextRetry,
		Attempts:  rec.Attempts,
	}
}

