// Package relayproof implements cross-chain message verification.
package relayproof

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"sync"
	"syscall"
)

// Header is a light-client header at a known height.
type Header struct {
	Chain   string
	Height  int64
	Root    string
	Trusted bool
}

// Message is one outbound cross-chain message awaiting delivery.
type Message struct {
	ID      string
	From    string
	To      string
	Nonce   uint64
	Payload string
	ProofAt int64
}

// Delivery is the outcome of a relay attempt.
type Delivery struct {
	Message string
	Status  string
	Reason  string
}

// Verify accepts a message only when the header covering it is known and trusted.
func Verify(headers map[string]Header, message Message, consumed map[string]bool) Delivery {
	header, ok := headers[message.From]
	if !ok {
		return Delivery{Message: message.ID, Status: "rejected", Reason: "unknown source chain"}
	}
	if !header.Trusted || header.Height < message.ProofAt {
		return Delivery{Message: message.ID, Status: "pending", Reason: "header not yet trusted at proof height"}
	}
	key := message.From + ":" + message.To + ":" + strconv.FormatUint(message.Nonce, 10)
	if consumed[key] {
		return Delivery{Message: message.ID, Status: "rejected", Reason: "replay: nonce already consumed"}
	}
	consumed[key] = true
	return Delivery{Message: message.ID, Status: "delivered", Reason: "proof verified at height " + strconv.FormatInt(header.Height, 10)}
}

// Pending lists messages still waiting for a trusted header, stable by id.
func Pending(headers map[string]Header, messages []Message) []string {
	var ids []string
	for _, message := range messages {
		header, ok := headers[message.From]
		if !ok || !header.Trusted || header.Height < message.ProofAt {
			ids = append(ids, message.ID)
		}
	}
	sort.Strings(ids)
	return ids
}

// Terminal message statuses.
const (
	StatusSuccess      = "success"       // delivered: recorded locally and nonce consumed
	StatusReplay       = "replay"        // terminal: nonce combination already consumed by another message
	StatusExpired      = "expired"       // terminal: absolute expiry reached before delivery
	StatusUnknownSrc   = "unknown-source" // terminal: source chain was never registered
	StatusPending      = "pending"       // accepted, not processed for the first time yet
	StatusWaiting      = "waiting"       // processed, waiting for a trusted header at proof height
)

// Common errors. Callers can compare with errors.Is.
var (
	// ErrConflict is returned when an id is reused with different message content.
	ErrConflict = errors.New("message id conflict: existing record has different content")
	// ErrTerminal is returned when a terminal message is submitted again or re-activated
	// through a header update.
	ErrTerminal = errors.New("message is terminal and cannot be reactivated")
	// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
	ErrInvalidArg = errors.New("invalid argument")
	// ErrLocked is returned when another process holds the state directory open.
	ErrLocked = errors.New("state directory is locked by another process")
	// ErrCorrupt is returned when the state directory contains unreadable state.
	ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
)

// Envelope is a submitted message together with its absolute expiry time.
type Envelope struct {
	Message Message
	// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
	ExpiresAt int64
}

// Record is the full persisted state of one submitted message.
type Record struct {
	Msg        Envelope
	Status     string
	Reason     string
	Seq        int64 // submission order, zero-based
	Attempts   int
	NextRetry  int64 // 0 when not yet processed for the first time, or terminal
	LastProcAt int64 // processing time of the most recent Advance that touched it
}

// Query is the user-visible view of a Record.
type Query struct {
	ID         string
	From       string
	To         string
	Nonce      uint64
	Payload    string
	ProofAt    int64
	ExpiresAt  int64
	Status     string
	Reason     string
	NextRetry  int64 // 0 = no retry scheduled
	Attempts   int
}

// Result describes what happened to one message during an Advance.
type Result struct {
	ID     string
	Status string
	Reason string
}

// AdvanceReport is the outcome of one Advance call.
type AdvanceReport struct {
	Now     int64
	Results []Result
}

func nonceKey(from, to string, nonce uint64) string {
	return from + "\x00" + to + "\x00" + strconv.FormatUint(nonce, 10)
}

// Queue is a durable local outbox. A single Queue owns its state directory for
// writes; other processes attempting to Open the same directory fail with
// ErrLocked. The Queue is safe for concurrent use by multiple goroutines.
type Queue struct {
	mu sync.Mutex

	store *store
	flock *os.File

	now      int64                 // last advanced time (Unix ms), 0 = never advanced
	sources  map[string]bool       // registered source chains
	headers  map[string]Header     // latest registered header per chain
	records  map[string]*Record    // by message id
	order    []string              // submission order of all non-terminal messages
	consumed map[string]string     // nonce combination -> id of the successful message
	nextSeq  int64
}

// Open opens (creating if needed) a persistent queue backed by stateDir.
// It takes an exclusive process lock on the directory and refuses to start
// when the on-disk state is corrupt or in an unsupported format.
func Open(stateDir string) (*Queue, error) {
	if stateDir == "" {
		return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
	}
	if err := os.MkdirAll(stateDir, 0o755); err != nil {
		return nil, fmt.Errorf("create state directory: %w", err)
	}
	abs, err := filepath.Abs(stateDir)
	if err != nil {
		return nil, fmt.Errorf("resolve state directory: %w", err)
	}

	lockPath := filepath.Join(abs, "lock")
	lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, fmt.Errorf("open lock file: %w", err)
	}
	if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		lock.Close()
		return nil, fmt.Errorf("%w: %v", ErrLocked, err)
	}

	st, err := openStore(abs)
	if err != nil {
		syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
		lock.Close()
		return nil, err
	}

	q := &Queue{
		store:    st,
		flock:    lock,
		sources:  map[string]bool{},
		headers:  map[string]Header{},
		records:  map[string]*Record{},
		consumed: map[string]string{},
	}
	if err := q.load(); err != nil {
		st.close()
		syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
		lock.Close()
		return nil, err
	}
	return q, nil
}

// Close flushes pending state, releases the directory lock and closes the queue.
func (q *Queue) Close() error {
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.flock == nil {
		return nil
	}
	err := q.store.close()
	syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
	q.flock.Close()
	q.flock = nil
	return err
}

// RegisterSource records that messages may originate from chain. It is idempotent.
func (q *Queue) RegisterSource(chain string) error {
	if chain == "" {
		return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.sources[chain] {
		return nil
	}
	if err := q.store.appendRegisterSource(chain); err != nil {
		return err
	}
	q.sources[chain] = true
	return nil
}

// UpsertHeader stores the latest known header for a chain. A header with
// trusted=false records the chain tip without granting proof coverage; a
// later trusted header covering the proof height can unblock messages.
// Header updates never bypass retry scheduling and never reactivate terminal
// messages.
func (q *Queue) UpsertHeader(h Header) error {
	if h.Chain == "" {
		return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
	}
	if h.Height < 0 {
		return fmt.Errorf("%w: negative header height", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.store.appendHeader(h); err != nil {
		return err
	}
	q.headers[h.Chain] = h
	return nil
}

// Submit enqueues a message with an absolute expiry time (Unix milliseconds;
// zero means never expire). Re-submitting the same id with identical content
// returns the existing record without adding a queue entry; the same id with
// different content returns ErrConflict and leaves the original untouched;
// re-submitting a terminal id returns ErrTerminal.
//
// Durability: success is reported only after the message is reliably persisted.
func (q *Queue) Submit(env Envelope) (*Record, error) {
	m := env.Message
	if m.ID == "" {
		return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
	}
	if m.From == "" || m.To == "" {
		return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
	}
	if m.ProofAt < 0 {
		return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
	}
	if env.ExpiresAt < 0 {
		return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
	}

	q.mu.Lock()
	defer q.mu.Unlock()

	if existing, ok := q.records[m.ID]; ok {
		if sameEnvelope(existing.Msg, env) {
			return existing, nil
		}
		if isTerminal(existing.Status) {
			return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
		}
		return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
	}

	rec := &Record{
		Msg:    env,
		Status: StatusPending,
		Reason: "awaiting first processing",
		Seq:    q.nextSeq,
	}
	if err := q.store.appendSubmit(rec); err != nil {
		return nil, err
	}
	q.records[m.ID] = rec
	q.order = append(q.order, m.ID)
	q.nextSeq++
	return rec, nil
}

// Advance moves processing time forward to nowMs (Unix milliseconds). Equal
// time may be advanced repeatedly; going backwards is rejected without
// changing any state. Each advance:
//
//  1. accepts first-time processing for new messages when now has reached
//     their first processing time;
//  2. checks replay and expiry (replay wins when both hold; exactly reaching
//     the expiry instant counts as expired) for every non-terminal message;
//  3. then processes messages whose retry time has come, in first-submission
//     order.
//
// Messages from unregistered sources are permanently rejected as unknown
// source. Registered sources with an untrusted or insufficient header stay
// waiting and do not consume the nonce. Retry intervals are 1,2,4,... seconds,
// doubling up to a 60 second cap, computed from the actual processing time.
func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
	if nowMs < 0 {
		return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()

	if q.now != 0 && nowMs < q.now {
		return nil, fmt.Errorf("%w: processing time %d is before last advanced time %d", ErrInvalidArg, nowMs, q.now)
	}
	now := nowMs

	report := &AdvanceReport{Now: now}
	// Snapshot ids: terminalization mutates q.order.
	ids := append([]string(nil), q.order...)
	for _, id := range ids {
		rec := q.records[id]
		if rec == nil || isTerminal(rec.Status) {
			continue
		}
		if rec.Attempts == 0 {
			// First processing is accepted on the next advance after submission.
		} else if now < rec.NextRetry {
			continue
		}

		// Replay and expiry are evaluated on every processing opportunity.
		// Replay takes precedence when both hold.
		key := nonceKey(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
		if winner, taken := q.consumed[key]; taken && winner != id {
			if err := q.terminalize(rec, now, StatusReplay,
				"nonce already consumed by message "+winner); err != nil {
				return nil, err
			}
			report.Results = append(report.Results, Result{ID: id, Status: StatusReplay, Reason: rec.Reason})
			continue
		}
		if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
			if err := q.terminalize(rec, now, StatusExpired,
				"expired at "+strconv.FormatInt(rec.Msg.ExpiresAt, 10)); err != nil {
				return nil, err
			}
			report.Results = append(report.Results, Result{ID: id, Status: StatusExpired, Reason: rec.Reason})
			continue
		}

		h, registered := q.headers[rec.Msg.Message.From]
		if !q.sources[rec.Msg.Message.From] {
			// Permanent rejection: the source can never become valid mid-flight,
			// because submitting does not register a source.
			if err := q.terminalize(rec, now, StatusUnknownSrc,
				"unknown source chain "+rec.Msg.Message.From); err != nil {
				return nil, err
			}
			report.Results = append(report.Results, Result{ID: id, Status: Status, Reason: rec.Reason})
			continue
		}
		if !registered || !h.Trusted || h.Height < rec.Msg.Message.ProofAt {
			cur := h.Height
			if !registered {
				cur = 0
			}
			if err := q.markWaiting(rec, now,
				fmt.Sprintf("waiting for trusted header at height %d (current %d)", rec.Msg.Message.ProofAt, cur)); err != nil {
				return nil, err
			}
			report.Results = append(report.Results, Result{ID: id, Status: StatusWaiting, Reason: rec.Reason})
			continue
		}

		// Success: recording the success and consuming the nonce commit
		// atomically in one log entry; they can never take effect separately.
		if err := q.store.appendResult(now, rec, StatusSuccess,
			"delivered at height "+strconv.FormatInt(h.Height, 10), rec.Attempts+1,
			nextRetryDelay(rec.Attempts+1), key, id, true); err != nil {
			return nil, err
		}
		rec.Attempts++
		rec.LastProcAt = now
		rec.Status = StatusSuccess
		rec.Reason = "delivered at height " + strconv.FormatInt(h.Height, 10)
		rec.NextRetry = 0
		q.consumed[key] = id
		q.removeFromOrder(id)
		if err := q.store.appendAdvance(now); err != nil {
			return nil, err
		}
		q.now = now
		report.Results = append(report.Results, Result{ID: id, Status: StatusSuccess, Reason: rec.Reason})
	}

	if err := q.store.appendAdvance(now); err != nil {
		return nil, err
	}
	q.now = now
	return report, nil
}

// Query returns the current state of a message.
func (q *Queue) Query(id string) (Query, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	rec, ok := q.records[id]
	if !ok {
		return Query{}, false
	}
	return toQuery(rec), true
}

// Queries returns all records in first-submission order.
func (q *Queue) Queries() []Query {
	q.mu.Lock()
	defer q.mu.Unlock()
	out := make([]Query, 0, len(q.records))
	for _, rec := range q.records {
		out = append(out, toQuery(rec))
	}
	sort.Slice(out, func(i, j int) bool {
		ri, rj := q.records[out[i].ID], q.records[out[j].ID]
		return ri.Seq < rj.Seq
	})
	return out
}

// Now returns the last advanced processing time, or 0 if never advanced.
func (q *Queue) Now() int64 {
	q.mu.Lock()
	defer q.mu.Unlock()
	return q.now
}

func (q *Queue) terminalize(rec *Record, now int64, status, reason string) error {
	if err := q.store.appendResult(now, rec, status, reason, rec.Attempts+1, 0, "", "", false); err != nil {
		return err
	}
	rec.Attempts++
	rec.LastProcAt = now
	rec.Status = status
	rec.Reason = reason
	rec.NextRetry = 0
	q.removeFromOrder(rec.Msg.Message.ID)
	return nil
}

func (q *Queue) markWaiting(rec *Record, now int64, reason string) error {
	attempt := rec.Attempts + 1
	delay := nextRetryDelay(attempt)
	if err := q.store.appendResult(now, rec, StatusWaiting, reason, attempt, delay, "", "", false); err != nil {
		return err
	}
	rec.Attempts = attempt
	rec.LastProcAt = now
	rec.Status = StatusWaiting
	rec.Reason = reason
	rec.NextRetry = now + delay
	return nil
}

func (q *Queue) removeFromOrder(id string) {
	for i, cand := range q.order {
		if cand == id {
			q.order = append(q.order[:i], q.order[i+1:]...)
			return
		}
	}
}

// nextRetryDelay returns the backoff after attempt (1-based):
// 1s, 2s, 4s, 8s, 16s, 32s, 60s, 60s, ... in milliseconds.
func nextRetryDelay(attempt int) int64 {
	if attempt < 1 {
		attempt = 1
	}
	if attempt > 6 {
		return 60_000
	}
	return int64(1) << (attempt - 1) * 1000
}

func isTerminal(status string) bool {
	switch status {
	case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
		return true
	}
	return false
}

func sameEnvelope(a, b Envelope) bool {
	return a.ExpiresAt == b.ExpiresAt &&
		a.Message.ID == b.Message.ID &&
		a.Message.From == b.Message.From &&
		a.Message.To == b.Message.To &&
		a.Message.Nonce == b.Message.Nonce &&
		a.Message.Payload == b.Message.Payload &&
		a.Message.ProofAt == b.Message.ProofAt
}

func toQuery(rec *Record) Query {
	return Query{
		ID:        rec.Msg.Message.ID,
		From:      rec.Msg.Message.From,
		To:        rec.Msg.Message.To,
		Nonce:     rec.Msg.Message.Nonce,
		Payload:   rec.Msg.Message.Payload,
		ProofAt:   rec.Msg.Message.ProofAt,
		ExpiresAt: rec.Msg.ExpiresAt,
		Status:    rec.Status,
		Reason:    rec.Reason,
		NextRetry: rec.NextRetry,
		Attempts:  rec.Attempts,
	}
}

input.content:
package relayproof

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
)

// On-disk format (queue.log):
//
//	magic   = "RELAYPROOF-QUEUE-V1\n"
//	record  = uint32-be length(N) | N bytes of JSON entry
//
// The log is an append-only write-ahead log. Every mutating operation is
// persisted as one framed record and fsynced before the operation is
// acknowledged; a success record frames the local success entry and the nonce
// consumption together, so the two can never take effect separately.
//
// A torn final record (crash while writing an unacknowledged entry) is the
// only tolerated damage: it is truncated at load because such an entry was
// never reported as durable. Any other damage or unknown format rejects the
// directory with ErrCorrupt; state is never silently cleared.

const (
	logName          = "queue.log"
	logMagic         = "RELAYPROOF-QUEUE-V1\n"
	compactThreshold = 4 << 20 // bytes; compact when the active log grows past this
	compactFileMode  = 0o600
)

// JSON log entry kinds.
const (
	kindVersion  = "version"
	kindSource   = "source"
	kindHeader   = "header"
	kindSubmit   = "submit"
	kindResult   = "result"
	kindAdvance  = "advance"
	currentLogV  = 1
)

type logEntry struct {
	T string `json:"t"`
	V int    `json:"v,omitempty"`

	Chain   string  `json:"chain,omitempty"`
	Height  int64   `json:"height,omitempty"`
	Root    string  `json:"root,omitempty"`
	Trusted bool    `json:"trusted,omitempty"`

	Seq       int64  `json:"seq,omitempty"`
	ID        string `json:"id,omitempty"`
	From      string `json:"from,omitempty"`
	To        string `json:"to,omitempty"`
	Nonce     uint64 `json:"nonce,omitempty"`
	Payload   string `json:"payload,omitempty"`
	ProofAt   int64  `json:"proofAt,omitempty"`
	ExpiresAt int64  `json:"expiresAt,omitempty"`

	Now        int64  `json:"now,omitempty"`
	Status     string `json:"status,omitempty"`
	Reason     string `json:"reason,omitempty"`
	Attempts   int    `json:"attempts,omitempty"`
	NextRetry  int64  `json:"nextRetry,omitempty"`
	ConsumeKey string `json:"consumeKey,omitempty"`
	ConsumeBy  string `json:"consumeBy,omitempty"`
}

type store struct {
	dir  string
	f    *os.File
	size int64
}

// loadedState is the fully replayed log content.
type loadedState struct {
	sources  map[string]bool
	headers  map[string]Header
	records  map[string]*Record
	consumed map[string]string
	nextSeq  int64
	now      int64
}

func openStore(dir string) (*store, error) {
	path := filepath.Join(dir, logName)

	info, err := os.Stat(path)
	switch {
	case err == nil:
		if info.IsDir() {
			return nil, fmt.Errorf("%w: %s is a directory", ErrCorrupt, logName)
		}
	case os.IsNotExist(err):
		if err := createLog(path, dir); err != nil {
			return nil, err
		}
	default:
		return nil, fmt.Errorf("stat %s: %w", logName, err)
	}

	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", logName, err)
	}
	goodLen, state, err := replayLog(raw)
	if err != nil {
		return nil, err
	}
	if int64(len(raw)) != goodLen {
		// Drop the torn tail of an entry that can never have been acknowledged.
		if err := os.Truncate(path, goodLen); err != nil {
			return nil, fmt.Errorf("truncate torn log tail: %w", err)
		}
		if err := syncDir(dir); err != nil {
			return nil, err
		}
	}

	f, err := os.OpenFile(path, os.O_RDWR|os.O_APPEND, compactFileMode)
	if err != nil {
		return nil, fmt.Errorf("open %s for append: %w", logName, err)
	}
	if _, err := f.Seek(0, io.SeekEnd); err != nil {
		f.Close()
		return nil, err
	}
	st := &store{dir: dir, f: f, size: goodLen}
	if err := st.applyLoaded(state); err != nil {
		f.Close()
		return nil, err
	}
	return st, nil
}

func createLog(path, dir string) error {
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, compactFileMode)
	if err != nil {
		return fmt.Errorf("create %s: %w", logName, err)
	}
	if _, err := f.WriteString(logMagic); err != nil {
		f.Close()
		return fmt.Errorf("write %s header: %w", logName, err)
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return fmt.Errorf("sync %s: %w", logName, err)
	}
	if err := f.Close(); err != nil {
		return err
	}
	return syncDir(dir)
}

// replayLog parses and validates the log, returning the byte length of the
// longest intact prefix and the reconstructed state.
func replayLog(raw []byte) (int64, *loadedState, error) {
	if !bytes.HasPrefix(raw, []byte(logMagic)) {
		return 0, nil, fmt.Errorf("%w: missing %s header", ErrCorrupt, logMagic)
	}
	pos := len(logMagic)
	state := &loadedState{
		sources:  map[string]bool{},
		headers:  map[string]Header{},
		records:  map[string]*Record{},
		consumed: map[string]string{},
	}

	first := true
	for pos < len(raw) {
		if len(raw)-pos < 4 {
			// Torn length header of an unacknowledged entry.
			return int64(pos), state, nil
		}
		n := int(binary.BigEndian.Uint32(raw[pos : pos+4]))
		if n == 0 {
			return 0, nil, fmt.Errorf("%w: zero-length record at offset %d", ErrCorrupt, pos)
		}
		start := pos + 4
		end := start + n
		if end > len(raw) {
			// Torn record body of an unacknowledged entry.
			return int64(pos), state, nil
		}
		var e logEntry
		if err := json.Unmarshal(raw[start:end], &e); err != nil {
			return 0, nil, fmt.Errorf("%w: invalid record at offset %d: %v", ErrCorrupt, pos, err)
		}
		if first {
			if e.T != kindVersion || e.V != currentLogV {
				return 0, nil, fmt.Errorf("%w: unsupported log version entry %+v", ErrCorrupt, e)
			}
			first = false
		} else if err := applyEntry(state, &e); err != nil {
			return 0, nil, err
		}
		pos = end
	}
	if first {
		return 0, nil, fmt.Errorf("%w: missing version record", ErrCorrupt)
	}
	return int64(pos), state, nil
}

func applyEntry(s *loadedState, e *logEntry) error {
	corrupt := func(msg string, args ...any) error {
		return fmt.Errorf("%w: %s", ErrCorrupt, fmt.Sprintf(msg, args...))
	}
	switch e.T {
	case kindVersion:
		return corrupt("unexpected version record")
	case kindSource:
		if e.Chain == "" {
			return corrupt("source entry with empty chain")
		}
		s.sources[e.Chain] = true
	case kindHeader:
		if e.Chain == "" || e.Height < 0 {
			return corrupt("bad header entry: %+v", e)
		}
		s.headers[e.Chain] = Header{Chain: e.Chain, Height: e.Height, Root: e.Root, Trusted: e.Trusted}
	case kindSubmit:
		if e.ID == "" || e.From == "" || e.To == "" || e.ProofAt < 0 || e.ExpiresAt < 0 {
			return corrupt("bad submit entry: %+v", e)
		}
		if _, dup := s.records[e.ID]; dup {
			return corrupt("duplicate submit for id %q", e.ID)
		}
		if e.Seq != s.nextSeq {
			return corrupt("submit seq %d out of order, expected %d", e.Seq, s.nextSeq)
		}
		s.records[e.ID] = &Record{
			Msg: Envelope{
				Message: Message{
					ID:      e.ID,
					From:    e.From,
					To:      e.To,
					Nonce:   e.Nonce,
					Payload: e.Payload,
					ProofAt: e.ProofAt,
				},
				ExpiresAt: e.ExpiresAt,
			},
			Status: StatusPending,
			Reason: "awaiting first processing",
			Seq:    e.Seq,
		}
		s.nextSeq++
	case kindResult:
		rec, ok := s.records[e.ID]
		if !ok {
			return corrupt("result for unknown id %q", e.ID)
		}
		if isTerminal(rec.Status) {
			return corrupt("result for terminal id %q", e.ID)
		}
		if e.Now < rec.LastProcAt {
			return corrupt("result time %d before prior time %d for %q", e.Now, rec.LastProcAt, e.ID)
		}
		if e.Attempts != rec.Attempts+1 {
			return corrupt("attempts jump %d -> %d for %q", rec.Attempts, e.Attempts, e.ID)
		}
		if !validStatus(e.Status) || e.Status == StatusPending {
			return corrupt("bad result status %q for %q", e.Status, e.ID)
		}
		switch e.Status {
		case StatusWaiting:
			if e.NextRetry <= e.Now {
				return corrupt("waiting result without future retry for %q", e.ID)
			}
		case StatusSuccess:
			key := nonceKey(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
			if e.ConsumeKey != key || e.ConsumeBy != e.ID {
				return corrupt("success entry for %q carries mismatched nonce consumption", e.ID)
			}
			if winner, taken := s.consumed[key]; taken {
				return corrupt("nonce %s already consumed by %q while accepting %q", key, winner, e.ID)
			}
			if e.NextRetry != 0 {
				return corrupt("success entry for %q carries retry time", e.ID)
			}
			s.consumed[key] = e.ID
		default: // terminal failure kinds
			if e.NextRetry != 0 || e.ConsumeKey != "" || e.ConsumeBy != "" {
				return corrupt("terminal entry for %q carries scheduling/consume fields", e.ID)
			}
		}
		rec.Attempts = e.Attempts
		rec.LastProcAt = e.Now
		rec.Status = e.Status
		rec.Reason = e.Reason
		rec.NextRetry = e.NextRetry
		if e.Now > s.now {
			s.now = e.Now
		}
	case kindAdvance:
		if e.Now < s.now {
			return corrupt("advance checkpoint %d before known time %d", e.Now, s.now)
		}
		s.now = e.Now
	default:
		return corrupt("unknown record type %q", e.T)
	}
	return nil
}

func validStatus(s string) bool {
	switch s {
	case StatusPending, StatusWaiting, StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
		return true
	}
	return false
}

func (s *store) applyLoaded(state *loadedState) error {
	// loadedState is handed to the Queue by loadFrom; store itself stays opaque.
	s.pendingLoad = state
	return nil
}

func (s *store) close() error {
	if s.f == nil {
		return nil
	}
	err := s.f.Sync()
	cerr := s.f.Close()
	s.f = nil
	if err != nil {
		return err
	}
	return cerr
}

// append writes one framed, fsynced record.
func (s *store) append(e *logEntry) error {
	buf, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("encode log entry: %w", err)
	}
	frame := make([]byte, 4+len(buf))
	binary.BigEndian.PutUint32(frame, uint32(len(buf)))
	copy(frame[4:], buf)
	if _, err := s.f.Write(frame); err != nil {
		return fmt.Errorf("write %s: %w", logName, err)
	}
	if err := s.f.Sync(); err != nil {
		return fmt.Errorf("sync %s: %w", logName, err)
	}
	s.size += int64(len(frame))
	if s.size > compactThreshold {
		if err := s.compact(); err != nil {
			return fmt.Errorf("compact %s: %w", logName, err)
		}
	}
	return nil
}

func (s *store) appendVersion() error {
	return s.append(&logEntry{T: kindVersion, V: currentLogV})
}

func (s *store) appendRegisterSource(chain string) error {
	return s.append(&logEntry{T: kindSource, Chain: chain})
}

func (s *store) appendHeader(h Header) error {
	return s.append(&logEntry{T: kindHeader, Chain: h.Chain, Height: h.Height, Root: h.Root, Trusted: h.Trusted})
}

func (s *store) appendSubmit(rec *Record) error {
	m := rec.Msg.Message
	return s.append(&logEntry{
		T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
		Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
	})
}

// appendResult records one processing outcome. On success the nonce
// consumption (consumeKey/consumeBy) is part of the same durable record.
func (s *store) appendResult(now int64, rec *Record, status, reason string, attempts int, delay int64, consumeKey, consumeBy string, success bool) error {
	e := &logEntry{
		T: kindResult, Now: now, ID: rec.Msg.Message.ID,
		Status: status, Reason: reason, Attempts: attempts,
	}
	if status == StatusWaiting {
		e.NextRetry = now + delay
	}
	if success {
		e.ConsumeKey = consumeKey
		e.ConsumeBy = consumeBy
	}
	return s.append(e)
}

func (s *store) appendAdvance(now int64) error {
	return s.append(&logEntry{T: kindAdvance, Now: now})
}

// compact atomically replaces the log with a snapshot of current state.
// Called while Queue.mu is held.
func (s *store) compact() error {
	// Rebuild state from the current live log through Queue-provided accessor.
	state, err := s.readCurrent()
	if err != nil {
		return err
	}
	tmp := filepath.Join(s.dir, logName+".compact")
	f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, compactFileMode)
	if err != nil {
		return err
	}
	w := &store{f: f, dir: s.dir}
	if _, err := f.WriteString(logMagic); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := w.appendVersion(); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	for chain := range state.sources {
		if err := w.appendRegisterSource(chain); err != nil {
			f.Close()
			os.Remove(tmp)
			return err
		}
	}
	// Deterministic header order.
	chains := make([]string, 0, len(state.headers))
	for c := range state.headers {
		chains = append(chains, c)
	}
	sortStrings(chains)
	for _, c := range chains {
		if err := w.appendHeader(state.headers[c]); err != nil {
			f.Close()
			os.Remove(tmp)
			return err
		}
	}
	seqs := make([]int64, 0, len(state.records))
	bySeq := map[int64]*Record{}
	for _, rec := range state.records {
		seqs = append(seqs, rec.Seq)
		bySeq[rec.Seq] = rec
	}
	sortInt64s(seqs)
	for _, seq := range seqs {
		rec := bySeq[seq]
		if err := w.appendSubmit(rec); err != nil {
			f.Close()
			os.Remove(tmp)
			return err
		}
		if rec.Attempts > 0 {
			key, by := "", ""
			if rec.Status == StatusSuccess {
				key = nonceKey(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
				by = rec.Msg.Message.ID
			}
			delay := rec.NextRetry - rec.LastProcAt
			if rec.Status != StatusWaiting {
				delay = 0
			}
			if err := w.appendResult(rec.LastProcAt, rec, rec.Status, rec.Reason, rec.Attempts, delay, key, by, rec.Status == StatusSuccess); err != nil {
				f.Close()
				os.Remove(tmp)
				return err
			}
		}
	}
	if state.now > 0 {
		if err := w.appendAdvance(state.now); err != nil {
			f.Close()
			os.Remove(tmp)
			return err
		}
	}
	if err := f.Sync(); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, filepath.Join(s.dir, logName)); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := syncDir(s.dir); err != nil {
		return err
	}
	nf, err := os.OpenFile(filepath.Join(s.dir, logName), os.O_RDWR|os.O_APPEND, compactFileMode)
	if err != nil {
		return err
	}
	if _, err := nf.Seek(0, io.SeekEnd); err != nil {
		nf.Close()
		return err
	}
	s.f.Close()
	s.f = nf
	if info, err := nf.Stat(); err == nil {
		s.size = info.Size()
	}
	return nil
}

// pendingLoad bridges replay state from openStore to Queue.load; readCurrent
// is injected by the Queue after open so compaction can snapshot live state.
func sortStrings(v []string) {
	for i := 1; i < len(v); i++ {
		for j := i; j > 0 && v[j-1] > v[j]; j-- {
			v[j-1], v[j] = v[j], v[j-1]
		}
	}
}

func sortInt64s(v []int64) {
	for i := 1; i < len(v); i++ {
		for j := i; j > 0 && v[j-1] > v[j]; j-- {
			v[j-1], v[j] = v[j], v[j-1]
		}
	}
}

